{"sql": "SELECT 
    '1, 2, 3, 4, 5, 6, 8, 10' as s,
    list(
        SELECT trim(part) 
        FROM unnest(split(s, ',')) as part
    ) as parts"}

{"sql": "WITH split_data AS (
    SELECT 
        '1, 2, 3, 4, 5, 6, 8, 10' as s,
        unnest(split(s, ',')) as part
)
SELECT part, trim(part) as trimmed FROM split_data"}

{"sql": "WITH test AS (
    SELECT unnest(split('1, 2, 3', ',')) as part
)
SELECT part::VARCHAR FROM test"}
